"""Binary search: first index of target in a sorted list."""


def find_first(sorted_items, target):
    lo, hi = 0, len(sorted_items)
    while lo < hi:
        mid = (lo + hi) // 2
        if sorted_items[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo if lo < len(sorted_items) else -1

from searchkit.bisect import find_first


def test_present():
    assert find_first([1, 3, 5], 3) == 1


def test_absent_returns_minus_one():
    assert find_first([1, 3, 5], 4) == -1

